void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
// Normalized pixel coordinates (from 0 to 1)
vec2 uv = fragCoord/iResolution.xy;

// Time varying pixel color
float x = fragCoord.x/100.0;
float phase = iTime*1.0;

float ass = 0.0;
float arr[10];

arr[0] = -0.55;
arr[1] = 0.77;
arr[2] = 0.15;
arr[3] = -0.45;
arr[4] = -0.3;
arr[5] = 0.42;
arr[6] = 0.433;
arr[7] = -0.13;
arr[8] = 0.55;
arr[9] = 0.65;

for(float i=0.0; i<10.0; i+=1.0){
float k = pow(2.0, i);
ass += sin(iTime + arr[int(i)] * x ) * sin((x+ arr[int(i)] * phase)*k/2.0) / k / 4.0;
}

vec3 col = vec3(sin(iTime), distance(vec2(0, 0), fragCoord)/500.0, 0);

float val = 1.0- pow(abs(0.55 + sin(fragCoord.y*1.0 + 0.567)*0.05 - uv.y), 1.0) * (ass + 0.4)/(sin(iTime*2.0 + 1.11*x)*0.5+1.0)*32.0 ;
float val1 = 1.0- pow(abs(0.5 + sin(fragCoord.y*1.123 + 1.111)*0.05 - uv.y), 1.0) * (ass + 0.4)/(sin(iTime*2.0 - 2.0*x)*0.5+1.0)*32.0 ;
float val2 = 1.0- pow(abs(0.45 + sin(fragCoord.y*0.984 + 5.123)*0.05 - uv.y), 1.0) * (ass + 0.4)/(sin(iTime*5.1 - 0.67*x)*0.5+1.0) *32.0;
if(val > 0.0 || val1 > 0.0 || val2 > 0.0){
col = vec3 (1.0 - val, 1.0 - val1, 1.0 - val2);
}
else
col = vec3(0.0, 0.0, 0.0);

// Output to screen
fragColor = vec4(col,1.0);
}

